"""Forecast tomorrow's prep quantities from recent daily covers (moving average)."""
from statistics import mean

def forecast(history, window=7, per_cover=None):
    """history: dict of item -> list of daily usage (oldest first)."""
    out = {}
    for item, usage in history.items():
        recent = usage[-window:]
        out[item] = round(mean(recent), 1) if recent else 0.0
    return out

if __name__ == "__main__":
    demo = {"rice (lb)": [12, 14, 13, 15, 14, 16, 15], "chicken thighs (lb)": [8, 9, 7, 10, 9, 11, 10]}
    for item, qty in forecast(demo).items():
        print(f"{item}: prep {qty}")
